const linha = $input.first().json;
const pendentes = Array.isArray(linha.pendentes) ? linha.pendentes : [];
if (pendentes.length === 0) return [];

const grupos = new Map();
for (const n of pendentes) {
  const chave = (n.usuario_id || 'admins') + '|' + n.tipo;
  if (!grupos.has(chave)) grupos.set(chave, []);
  grupos.get(chave).push(n);
}

const assunto = (t) => {
  const p = String(t || '').split(': ');
  return (p.length > 1 ? p.slice(1).join(": ") : p[0]).trim();
};

const saida = [];
for (const [chave, itens] of grupos) {
  const primeiro = itens[0];
  const ids = itens.map((i) => String(i.id));
  let titulo = primeiro.titulo;
  let corpo = primeiro.corpo || '';

  if (itens.length > 1) {
    const total = Number(primeiro.fila_total) || itens.length;
    titulo = primeiro.tipo === 'followup'
      ? total + ' follow-ups esperando'
      : itens.length + ' avisos novos';
    const nomes = itens.map((i) => assunto(i.titulo)).filter(Boolean);
    corpo = nomes.slice(0, 3).join(", ")
      + (nomes.length > 3 ? ' e mais ' + (nomes.length - 3) : '');
  }

  saida.push({
    json: {
      chave,
      usuario_id: primeiro.usuario_id || null,
      tipo: primeiro.tipo,
      titulo: String(titulo).slice(0, 120),
      corpo: String(corpo).slice(0, 500),
      url: primeiro.url || '/followups',
      tag: primeiro.tipo,
      quantidade: itens.length,
      ids_pg: '{' + ids.join(',') + '}',
    },
  });
}

return saida;
